mapper.select:
SELECT workspace_id
FROM workflow_runtime_workspace
WHERE workspace_id > #{afterId}
ORDER BY workspace_id
LIMIT #{limit}

mapper.update:
UPDATE workflow_runtime_workspace
SET next_queue = #{nextQueue}, last_claimed_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}

mapper.select:
SELECT 
FROM workflow_trigger_outbox
WHERE workspace_id = #{workspaceId} AND id = #{id}

SELECT 
FROM workflow_trigger_outbox
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'leased'
  AND lease_owner = #{leaseOwner}
  AND lease_until >= CURRENT_TIMESTAMP(6)
FOR UPDATE

mapper.update:
UPDATE workflow_trigger_outbox
SET status = 'pending',
    available_at = DATE_ADD(
      CURRENT_TIMESTAMP(6), INTERVAL #{delaySeconds} SECOND),
    lease_owner = NULL,
    lease_until = NULL,
    last_error_code = #{errorCode}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'leased'
  AND lease_owner = #{leaseOwner}
  AND lease_until >= CURRENT_TIMESTAMP(6)

mapper.delete:
DELETE FROM workflow_trigger_outbox
WHERE workspace_id = #{workspaceId}
  AND status IN ('completed', 'invalidated')
  AND completed_at < #{cutoff}
ORDER BY id
LIMIT #{limit}

DELETE FROM workflow_trigger_outbox
WHERE workspace_id = #{workspaceId}
  AND status = 'dead'
  AND completed_at < #{cutoff}
ORDER BY id
LIMIT #{limit}
